// Handler creates http.Handler with routing matching OpenAPI spec.
func Handler(si ServerInterface) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{})
}

type ChiServerOptions struct {
	BaseURL          string
	BaseRouter       chi.Router
	Middlewares      []MiddlewareFunc
	ErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

// HandlerFromMux creates http.Handler with routing matching OpenAPI spec based on the provided mux.
func HandlerFromMux(si ServerInterface, r chi.Router) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{
		BaseRouter: r,
	})
}

func HandlerFromMuxWithBaseURL(si ServerInterface, r chi.Router, baseURL string) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{
		BaseURL:    baseURL,
		BaseRouter: r,
	})
}

// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options ChiServerOptions) http.Handler {
	r := options.BaseRouter

	if r == nil {
		r = chi.NewRouter()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/enterprise/hosts/name-availability", wrapper.CheckHostNameAvailability)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/enterprise/hosts", wrapper.ListHosts)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/enterprise/hosts/{id}", wrapper.GetHost)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/enterprise/hosts/actions/preview-create", wrapper.PreviewCreateHost)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/enterprise/hosts/{id}/actions/preview-retry", wrapper.PreviewRetryHost)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/enterprise/hosts/{id}/actions/preview-update", wrapper.PreviewUpdateHost)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/enterprise/hosts/{id}/actions/preview-delete", wrapper.PreviewDeleteHost)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/enterprise/hosts/connection-tests", wrapper.CreateHostConnectionTest)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/enterprise/host-onboarding-operations/{id}", wrapper.GetHostOnboardingOperation)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/enterprise/host-removals/connection-defaults", wrapper.GetHostRemovalConnectionDefaults)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/enterprise/host-removals/actions/preview", wrapper.PreviewHostRemoval)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/enterprise/host-removal-operations/{id}", wrapper.GetHostRemovalOperation)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/enterprise/host-removal-operations/{id}/actions/retry", wrapper.RetryHostRemovalOperation)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/enterprise/host-removal-operations/{id}/actions/regenerate-command", wrapper.RegenerateHostRemovalCommand)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/host-removal/bootstrap-script", wrapper.GetHostRemovalBootstrapScript)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/host-removal/receipt", wrapper.SubmitHostRemovalReceipt)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/enterprise/hosts/{id}/windows-rdp/actions/preview-enable", wrapper.PreviewEnableHostWindowsRDP)
	})

	return r
}

